import{_ as e,o as n,c as t,a0 as i}from"./chunks/framework.DhQjJcnt.js";const p=JSON.parse('{"title":"Skill: /api-update","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/api-update.md","filePath":"references/skills/api-update.md"}'),o={name:"references/skills/api-update.md"};function l(c,a,d,r,s,h){return n(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="skill-api-update" tabindex="-1">Skill: <code>/api-update</code> <a class="header-anchor" href="#skill-api-update" aria-label="Permalink to &quot;Skill: `/api-update`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>api-update</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/api-update &lt;page-id/slug&gt;</code> (Mặc định: Đồng bộ thay đổi từ Portal FE sang Backend API).</li><li>Chế độ Backend Only: <code>/api-update &lt;page-id/slug&gt; --be-only</code> (Chỉ cập nhật logic ngầm, không làm thay đổi giao thức kết nối với Frontend).</li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>Đọc file <code>ir/design.yaml</code> (dữ liệu từ FE Portal).</li><li>Đọc file hợp đồng Backend hiện hành: <code>api/&lt;seq&gt;/01-backend-spec.yaml</code> (và <code>03-mock-data.yaml</code>).</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>File <code>01-backend-spec.yaml</code> (và file mock data) được vá/cập nhật (Delta Patch).</li><li>Ghi log thay đổi vào <code>changeLog</code> và tự động tăng <code>feature.version</code> trong file <code>01</code>.</li><li>Chạy lệnh CLI để kiểm định và sinh lại OpenAPI: <code>flowgrid openapi_gen</code>.</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Dùng để <strong>Đồng bộ hóa (Sync) / Cập nhật (Update)</strong> hợp đồng Backend API khi giao diện Frontend (Portal) có sự thay đổi về đặc tả, hoặc khi team Backend có những yêu cầu logic ngầm mới (BE-only requirements).</li><li>Tương tự như <code>/update-spec</code> (sửa FE), kỹ năng này chỉ cập nhật cục bộ (Patch) dựa trên những điểm khác biệt (Diff). Tuyệt đối không viết lại toàn bộ file từ đầu hay tự ý thiết kế lại API.</li><li>Cấm sửa đổi tên các trường (API fields) một cách tuỳ tiện chỉ để &quot;cho tiện&quot; bên Frontend.</li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li><strong>Trước đó:</strong> Giao diện FE thay đổi thông qua <code>/update-spec</code>.</li><li><strong>Sau đó:</strong> Bắt buộc gọi <code>/grill-api-spec</code> để chạy lại kiểm toán kỹ thuật và gỡ/thêm các nhãn gencode (codegen tags).</li></ul><h2 id="chu-y-quan-trong" tabindex="-1">Chú ý quan trọng <a class="header-anchor" href="#chu-y-quan-trong" aria-label="Permalink to &quot;Chú ý quan trọng&quot;">​</a></h2><ul><li><strong>Cấm đoán:</strong> Tuyệt đối không sinh file Markdown report, không sinh mã nguồn Laravel/Python.</li><li>Nếu đụng tới các liên kết ngoại (External Integrations), phải dùng form AskQuestion (có option &quot;Log as Tech Debt&quot;). Nếu User chọn Tech Debt, sinh file trong <code>qa-inbox.md</code> và xử lý sau bằng <code>/qa-resolve</code>.</li><li>File <code>02-openapi.yaml</code> là file <strong>gen tự động</strong>, cấm được patch/sửa tay trực tiếp vào nó. Chỉ sửa <code>01</code> và chạy lệnh gen.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/api-update</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',20)])])}const g=e(o,[["render",l]]);export{p as __pageData,g as default};
